(function(){
const fmt=n=>new Intl.NumberFormat("en-IN").format(Math.round(Number(n)||0)),pct=n=>`${(Number(n)||0).toFixed(1)}%`,duration=s=>{s=Math.round(Number(s)||0);return `${Math.floor(s/60)}:${String(s%60).padStart(2,"0")}`},hours=m=>`${((Number(m)||0)/60).toFixed(1)} hrs`,labels={RELATED_VIDEO:"Suggested videos",YT_OTHER_PAGE:"Other YouTube pages",PLAYLIST:"Playlists",SUBSCRIBER:"Subscriptions feed",SHORTS:"Shorts feed",YT_SEARCH:"YouTube search",NO_LINK_OTHER:"Direct or unknown",YT_CHANNEL:"Channel pages",EXT_URL:"External",NOTIFICATION:"Notifications",MOBILE:"Mobile",DESKTOP:"Computer",TABLET:"Tablet",TV:"TV",GAME_CONSOLE:"Game console",SUBSCRIBED:"Subscribed",UNSUBSCRIBED:"Not subscribed",MALE:"Male",FEMALE:"Female",USER_SPECIFIED:"User specified"};
const label=s=>labels[s]||(s||"Other").replaceAll("_"," ").toLowerCase().replace(/^./,c=>c.toUpperCase());
const sum=(rows,key)=>rows.reduce((total,row)=>total+Number(row[key]||0),0);
function cards(items){return `<div class="video-metrics">${items.map(([name,value,note])=>`<div><span>${name}</span><b>${value}</b>${note?`<small>${note}</small>`:""}</div>`).join("")}</div>`}
function bars(rows,key,nameKey){const total=sum(rows,key);if(!rows.length||!total)return '<p class="video-empty">Not enough verified data is available for this video yet.</p>';return `<div class="video-bars">${rows.slice(0,10).map(row=>{const value=Number(row[key]||0),percent=value*100/total;return `<div><span>${label(row[nameKey])}</span><b>${fmt(value)} <small>(${percent.toFixed(1)}%)</small></b><i><em style="width:${Math.max(1,percent)}%"></em></i></div>`}).join("")}</div>`}
function retention(rows){if(!rows.length)return '<p class="video-empty">Audience-retention curve will appear after YouTube has enough viewer data.</p>';return `<div class="retention-chart" aria-label="Audience retention chart">${rows.map((row,i)=>`<i style="height:${Math.min(100,Number(row.audienceWatchRatio||0)*100)}%" title="${Math.round(Number(row.elapsedVideoTimeRatio||0)*100)}% · ${pct(Number(row.audienceWatchRatio||0)*100)} retained"></i>`).join("")}</div><div class="retention-axis"><span>Start</span><span>Middle</span><span>End</span></div>`}
function demographics(rows){if(!rows.length)return '<p class="video-empty">Age and gender data is unavailable, usually because the audience threshold has not been reached.</p>';return bars(rows,"viewerPercentage","gender")}
function render(target,data,tab){const s=data.summary||{},v=data.video||{},views=Number(s.views||v.viewCount||0),tabs={
overview:cards([["Views",fmt(v.viewCount||views),"Current public total"],["Watch time",hours(s.estimatedMinutesWatched),"Selected video"],["Subscribers",`${Number(s.subscribersGained||0)-Number(s.subscribersLost||0)>=0?"+":""}${fmt(Number(s.subscribersGained||0)-Number(s.subscribersLost||0))}`,"Net gained"],["Avg. duration",duration(s.averageViewDuration),pct(s.averageViewPercentage)+" viewed"]])+`<h3>Daily performance</h3>${bars(data.daily||[],"views","day")}`,
reach:`${data.reach?.available?`${!data.reach.completePeriod?`<div class="reach-status"><b>Partial Reporting API history</b><p>Verified impression activity currently available from ${data.reach.coverageStart||"—"} to ${data.reach.coverageEnd||"—"} (${data.reach.reportedDays} activity days). In YouTube Studio, select the same custom dates for comparison. More historical reports will be included automatically when YouTube releases them.</p></div>`:""}${cards([["Thumbnail impressions",fmt(data.reach.impressions),`${data.reach.reportedDays} days with reported activity`],["Impressions CTR",pct(data.reach.ctrPercent),"Weighted for available dates"],["Thumbnail clicks",fmt(data.reach.estimatedClicks),"Calculated: impressions × CTR"]])}`:`<div class="reach-status"><b>Thumbnail reach data</b><p>${data.reach?.message||"YouTube is preparing the report."}</p></div>`}${cards([["Analytics views",fmt(views),"Processed by YouTube"],["Traffic sources",fmt((data.traffic||[]).length),"Verified source types"],["Devices",fmt((data.devices||[]).length),"Viewer device types"]])}<div class="video-two"><section><h3>How viewers found this video</h3>${bars(data.traffic||[],"views","insightTrafficSourceType")}</section><section><h3>Device type</h3>${bars(data.devices||[],"views","deviceType")}</section></div><p class="api-note">Reach figures update after YouTube Reporting processing. Thumbnail clicks are calculated from verified impressions and CTR because the API does not provide a separate click total.</p>`,
engagement:`${cards([["Watch time",hours(s.estimatedMinutesWatched)],["Avg. duration",duration(s.averageViewDuration)],["Avg. viewed",pct(s.averageViewPercentage)],["Likes",fmt(v.likeCount||s.likes)],["Comments",fmt(v.commentCount||s.comments)],["Shares",fmt(s.shares)]])}<h3>Cards</h3>${cards([["Card impressions",fmt(data.cards?.cardImpressions)],["Card clicks",fmt(data.cards?.cardClicks)],["Card click rate",pct(data.cards?.cardClickRate)],["Teaser impressions",fmt(data.cards?.cardTeaserImpressions)],["Teaser clicks",fmt(data.cards?.cardTeaserClicks)]])}<h3>End screen</h3>${cards([["Element impressions",fmt(data.endScreens?.endScreenElementImpressions)],["Element clicks",fmt(data.endScreens?.endScreenElementClicks)],["Click rate",pct(data.endScreens?.endScreenElementClickRate)]])}<h3>Audience retention</h3>${retention(data.retention||[])}`,
audience:`${cards([["Subscribers gained",`+${fmt(s.subscribersGained)}`],["Subscribers lost",fmt(s.subscribersLost)],["Top countries",fmt((data.countries||[]).length)]])}<div class="video-two"><section><h3>Subscribed status</h3>${bars(data.subscribed||[],"views","subscribedStatus")}</section><section><h3>Top countries</h3>${bars(data.countries||[],"views","country")}</section></div><h3>Age and gender</h3>${demographics(data.demographics||[])}`};target.querySelector(".video-tab-content").innerHTML=tabs[tab]||tabs.overview;target.querySelectorAll(".video-tabs button").forEach(button=>{button.classList.toggle("active",button.dataset.tab===tab);button.setAttribute("aria-selected",button.dataset.tab===tab)})}
async function open(video,dialogId,targetId){const id=video.id||video.videoId,dialog=document.getElementById(dialogId),target=document.getElementById(targetId),title=video.title||"Video analytics",thumb=video.thumb||video.thumbnail||"";target.innerHTML=`<div class="video-detail-head"><img src="${thumb}" alt=""><div><p class="overline">VIDEO ANALYTICS</p><h2>${title}</h2><a href="https://youtu.be/${id}" target="_blank" rel="noopener">Open on YouTube ↗</a></div></div><div class="video-tabs" role="tablist" aria-label="Video analytics sections">${[["overview","Overview"],["reach","Reach"],["engagement","Engagement"],["audience","Audience"]].map(([key,name])=>`<button role="tab" data-tab="${key}" aria-selected="${key==="overview"}">${name}</button>`).join("")}</div><div class="video-tab-content"><p class="video-loading">Loading verified YouTube analytics…</p></div>`;dialog.showModal();try{const response=await fetch(`video.json?id=${encodeURIComponent(id)}&t=${Date.now()}`,{cache:"no-store"}),data=await response.json();if(!response.ok||data.error)throw new Error(data.error);render(target,data,"overview");target.querySelectorAll(".video-tabs button").forEach(button=>button.onclick=()=>render(target,data,button.dataset.tab))}catch(error){target.querySelector(".video-tab-content").innerHTML='<p class="video-empty">Detailed analytics is temporarily unavailable. Please try again shortly.</p>'}}
window.openVideoAnalytics=open;
})();
